package lab.backend.learning.contentreplica;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.Map;
import java.util.UUID;
import java.util.function.Supplier;
import javax.sql.DataSource;

/** Durable participant effects; each phase receipt and its state transition commit atomically. */
public final class PublicationStore {
  private final DataSource source;private final UUID realm,generation;private final PublicationGate gate;
  public PublicationStore(DataSource source,UUID realm,UUID generation,PublicationGate gate){this.source=source;this.realm=realm;this.generation=generation;this.gate=gate;}
  /** Duplicate lookup holds no publication gate or row lock and permits lost-ACK recovery without INT-03. */
  public byte[] existing(PublicationWire.Command c){return tx(db->{environment(db,c);return receipt(db,c);});}
  /**
   * Giữ shared gate từ lúc đọc durable fence đến khi callback kết thúc. Vì vậy
   * FENCE không thể chen giữa phép kiểm tra và effect, còn fence đã commit vẫn
   * trả publication_pending sau restart thay vì dựa vào state trong memory.
   */
  public <T>T contentSensitive(Supplier<T> callback,Supplier<T> pending){return gate.contentSensitive(()->isFenced()?pending.get():callback.get());}
  public byte[] stage(PublicationWire.Command c,ReplicaValidator.Verified replica){return gate.exclusive(()->tx(db->{environment(db,c);publicationLock(db);byte[] prior=receipt(db,c);if(prior!=null)return prior;expectNextSequence(db,c);head(db,c.parentRevision(),false,null);try(var s=db.prepareStatement("INSERT INTO learning.content_replica(bundle_id,target_revision,bundle_sha256,manifest_sha256,bundle_bytes,manifest_bytes) VALUES (?,?,?,?,?,?) ON CONFLICT DO NOTHING")){s.setString(1,c.bundleId());s.setLong(2,c.targetRevision());s.setString(3,c.bundleSha256());s.setString(4,c.manifestSha256());s.setBytes(5,replica.bundle());s.setBytes(6,replica.manifest());s.executeUpdate();}verifyReplica(db,c);try(var s=db.prepareStatement("INSERT INTO learning.publication_operation VALUES (?,?,?,?,?,?,?,?,?,'STAGED')")){s.setObject(1,c.operationId());s.setLong(2,c.parentRevision());s.setLong(3,c.targetRevision());s.setString(4,c.bundleId());s.setString(5,c.bundleSha256());s.setString(6,c.manifestSha256());s.setObject(7,c.realmId());s.setObject(8,c.producerGeneration());s.setObject(9,c.participantGeneration());s.executeUpdate();}return save(db,c,"STAGED");}));}
  public byte[] phase(PublicationWire.Command c){return gate.exclusive(()->tx(db->{environment(db,c);publicationLock(db);byte[] prior=receipt(db,c);if(prior!=null)return prior;expectNextSequence(db,c);String current=operation(db,c);return switch(c.phase()){case "FENCE"->{if(!"STAGED".equals(current))conflict();head(db,c.parentRevision(),false,null);try(var s=db.prepareStatement("UPDATE learning.publication_head SET fence_operation=? WHERE singleton AND fence_operation IS NULL")){s.setObject(1,c.operationId());if(s.executeUpdate()!=1)conflict();}state(db,c,"FENCED");yield save(db,c,"FENCED");}case "RELEASE"->{if(!"FENCED".equals(current))conflict();head(db,c.parentRevision(),true,c.operationId());try(var s=db.prepareStatement("UPDATE learning.publication_head SET applied_revision=?,active_bundle_id=?,active_manifest_sha256=?,fence_operation=NULL WHERE singleton")){s.setLong(1,c.targetRevision());s.setString(2,c.bundleId());s.setString(3,c.manifestSha256());s.executeUpdate();}state(db,c,"RELEASED");yield save(db,c,"RELEASED");}case "ABORT"->{if(!SetLike.of("STAGED","FENCED").contains(current))conflict();try(var s=db.prepareStatement("UPDATE learning.publication_head SET fence_operation=NULL WHERE singleton AND (fence_operation IS NULL OR fence_operation=?)")){s.setObject(1,c.operationId());if(s.executeUpdate()!=1)conflict();}state(db,c,"ABORTED");yield save(db,c,"ABORTED");}default->throw new IllegalArgumentException("STAGE_REQUIRES_REPLICA");};}));}
  public Map<String,Object> status(UUID operation){return tx(db->{try(var s=db.prepareStatement("SELECT o.state,o.parent_revision,o.target_revision,o.bundle_id,o.bundle_sha256,o.manifest_sha256,o.realm_id,o.producer_generation,o.participant_generation,r.phase,r.delivery_sequence,r.command_sha256 FROM learning.publication_operation o JOIN learning.publication_receipt r ON r.operation_id=o.operation_id AND r.phase=CASE o.state WHEN 'STAGED' THEN 'STAGE' WHEN 'FENCED' THEN 'FENCE' WHEN 'RELEASED' THEN 'RELEASE' ELSE 'ABORT' END WHERE o.operation_id=?")){s.setObject(1,operation);try(var r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("OPERATION_NOT_FOUND");return Map.ofEntries(Map.entry("contractVersion",1),Map.entry("operationId",operation.toString()),Map.entry("phase",r.getString(10)),Map.entry("state",r.getString(1)),Map.entry("parentRevision",r.getLong(2)),Map.entry("targetRevision",r.getLong(3)),Map.entry("bundleId",r.getString(4)),Map.entry("bundleSha256",r.getString(5)),Map.entry("manifestSha256",r.getString(6)),Map.entry("realmId",r.getObject(7,UUID.class).toString()),Map.entry("producerGeneration",r.getObject(8,UUID.class).toString()),Map.entry("participantGeneration",r.getObject(9,UUID.class).toString()),Map.entry("deliverySequence",r.getLong(11)),Map.entry("commandSha256",r.getString(12)));}}});}
  private void environment(Connection db,PublicationWire.Command c)throws SQLException{if(!realm.equals(c.realmId())||!generation.equals(c.participantGeneration()))conflict();/* Bảng môi trường chỉ do provisioner quản lý và bất biến với app; advisory transaction lock bên dưới mới tuần tự hóa phase. FOR SHARE ở đây vừa thừa vừa đòi quyền UPDATE. */try(var s=db.createStatement();var r=s.executeQuery("SELECT realm_id,db_generation,content_generation,ready FROM learning.publication_environment WHERE singleton")){if(!r.next()||!realm.equals(r.getObject(1,UUID.class))||!generation.equals(r.getObject(2,UUID.class))||!c.producerGeneration().equals(r.getObject(3,UUID.class))||!r.getBoolean(4))throw new IllegalStateException("PUBLICATION_NOT_READY");}}
  private static byte[] receipt(Connection db,PublicationWire.Command c)throws SQLException{try(var s=db.prepareStatement("SELECT command_sha256,receipt_bytes FROM learning.publication_receipt WHERE operation_id=? AND phase=?")){s.setObject(1,c.operationId());s.setString(2,c.phase());try(var r=s.executeQuery()){if(!r.next())return null;if(!c.commandSha256().equals(r.getString(1)))conflict();return r.getBytes(2);}}}
  /** Exact receipt cũ được trả trước hàm này; command mới phải nối đúng durable prefix content-global. */
  private static void expectNextSequence(Connection db,PublicationWire.Command c)throws SQLException{try(var s=db.prepareStatement("SELECT last_sequence FROM learning.publication_delivery_cursor WHERE stream_key='content-global' FOR UPDATE");var r=s.executeQuery()){if(!r.next())throw new IllegalStateException("PUBLICATION_NOT_READY");long last=r.getLong(1);if(last==Long.MAX_VALUE||c.deliverySequence()!=last+1)conflict();}}
  private boolean isFenced(){return tx(db->{try(var s=db.createStatement();var r=s.executeQuery("SELECT fence_operation IS NOT NULL FROM learning.publication_head WHERE singleton")){if(!r.next())throw new IllegalStateException("PUBLICATION_NOT_READY");return r.getBoolean(1);}});}
  private static void verifyReplica(Connection db,PublicationWire.Command c)throws SQLException{try(var s=db.prepareStatement("SELECT target_revision,bundle_sha256,manifest_sha256 FROM learning.content_replica WHERE bundle_id=?")){s.setString(1,c.bundleId());try(var r=s.executeQuery()){if(!r.next()||r.getLong(1)!=c.targetRevision()||!c.bundleSha256().equals(r.getString(2))||!c.manifestSha256().equals(r.getString(3)))conflict();}}}
  private static void publicationLock(Connection db)throws SQLException{try(var s=db.createStatement()){s.execute("SELECT pg_advisory_xact_lock(7406,1)");}}
  private static String operation(Connection db,PublicationWire.Command c)throws SQLException{try(var s=db.prepareStatement("SELECT state,parent_revision,target_revision,bundle_id,bundle_sha256,manifest_sha256,realm_id,producer_generation,participant_generation FROM learning.publication_operation WHERE operation_id=? FOR UPDATE")){s.setObject(1,c.operationId());try(var r=s.executeQuery()){if(!r.next()||r.getLong(2)!=c.parentRevision()||r.getLong(3)!=c.targetRevision()||!c.bundleId().equals(r.getString(4))||!c.bundleSha256().equals(r.getString(5))||!c.manifestSha256().equals(r.getString(6))||!c.realmId().equals(r.getObject(7,UUID.class))||!c.producerGeneration().equals(r.getObject(8,UUID.class))||!c.participantGeneration().equals(r.getObject(9,UUID.class)))conflict();return r.getString(1);}}}
  private static void head(Connection db,long revision,boolean fenced,UUID operation)throws SQLException{try(var s=db.prepareStatement("SELECT applied_revision,fence_operation FROM learning.publication_head WHERE singleton FOR UPDATE" );var r=s.executeQuery()){if(!r.next()||r.getLong(1)!=revision||(fenced&&!operation.equals(r.getObject(2,UUID.class)))||(!fenced&&r.getObject(2)!=null))conflict();}}
  private static void state(Connection db,PublicationWire.Command c,String state)throws SQLException{try(var s=db.prepareStatement("UPDATE learning.publication_operation SET state=? WHERE operation_id=?")){s.setString(1,state);s.setObject(2,c.operationId());if(s.executeUpdate()!=1)conflict();}}
  private static byte[] save(Connection db,PublicationWire.Command c,String state)throws Exception{byte[] bytes=PublicationWire.JSON.writeValueAsBytes(Map.ofEntries(Map.entry("contractVersion",1),Map.entry("operationId",c.operationId().toString()),Map.entry("phase",c.phase()),Map.entry("state",state),Map.entry("parentRevision",c.parentRevision()),Map.entry("targetRevision",c.targetRevision()),Map.entry("bundleId",c.bundleId()),Map.entry("bundleSha256",c.bundleSha256()),Map.entry("manifestSha256",c.manifestSha256()),Map.entry("realmId",c.realmId().toString()),Map.entry("producerGeneration",c.producerGeneration().toString()),Map.entry("participantGeneration",c.participantGeneration().toString()),Map.entry("deliverySequence",c.deliverySequence()),Map.entry("commandSha256",c.commandSha256())));try(var s=db.prepareStatement("INSERT INTO learning.publication_receipt(operation_id,phase,delivery_sequence,command_sha256,receipt_bytes) VALUES (?,?,?,?,?)")){s.setObject(1,c.operationId());s.setString(2,c.phase());s.setLong(3,c.deliverySequence());s.setString(4,c.commandSha256());s.setBytes(5,bytes);s.executeUpdate();}try(var s=db.prepareStatement("UPDATE learning.publication_delivery_cursor SET last_sequence=? WHERE stream_key='content-global' AND last_sequence=?")){s.setLong(1,c.deliverySequence());s.setLong(2,c.deliverySequence()-1);if(s.executeUpdate()!=1)conflict();}return bytes;}
  private <T>T tx(Sql<T> work){try(var db=source.getConnection()){db.setAutoCommit(false);try{try(var s=db.createStatement()){s.execute("SET LOCAL lock_timeout='5000ms'; SET LOCAL statement_timeout='5000ms'; SET LOCAL transaction_timeout='6000ms'");}T value=work.run(db);db.commit();return value;}catch(Exception e){try{db.rollback();}catch(Exception ignored){}if(e instanceof RuntimeException r)throw r;throw new IllegalStateException("PUBLICATION_UNAVAILABLE",e);}}catch(SQLException e){throw new IllegalStateException("PUBLICATION_UNAVAILABLE",e);}}
  private static void conflict(){throw new IllegalArgumentException("PUBLICATION_CONFLICT");}
  @FunctionalInterface private interface Sql<T>{T run(Connection db)throws Exception;}
  private static final class SetLike{static java.util.Set<String> of(String... values){return java.util.Set.of(values);}}
}
